shutdown() {
  try {
    const stmts = [
      this.stmtMarkDelete,
      this.stmtUnmarkDelete,
      this.stmtGet,
      this.stmtGetWithCal,
      this.stmtFlush,
    ];
    for (const stmt of stmts) {
      stmt.finalize();
    }

    if (this.mDB) {
      this.mDB.asyncClose();
      this.mDB = null;
    }
  } catch (e) {
    lazy.log.error("Error closing deleted items database: " + e);
  }

  cal.manager.removeCalendarObserver(this);
},
